/* BS 7671 course – Level 1 Foundations: M1 scope, definitions and principles · M2 earthing systems and supply · M3 identification and wiring systems.
   Requirements are explained in our own words with the regulation number to look up – no text of BS 7671 is reproduced. */
(function () {
  const pickTry = (arr) => () => { const [q, opts, c, how] = BS.pick(arr); return { q, opts, c, how }; };
  const R = BS.r, rnd = BS.rnd;

  // ================================================================ M1 · Scope, definitions and fundamental principles
  lesson('m1', '1.1', '📘', 'What BS 7671 covers – and what it does not', {
    regs: ['Part 1 · Chapter 11', 'Reg 110.1', 'Reg 110.2'],
    hook: 'A hotel client asks whether the lift motor wiring, the lightning protection on the roof and the shore supply for the hotel boat are "all to BS 7671". Some are, some are not – and the answer decides which standard your team builds and tests to.',
    rule: '<p>BS 7671 sets the requirements for the <b>design, erection and verification of electrical installations</b> – the fixed wiring from the origin (the supply terminals) to the points where equipment is connected – at up to <b>1000 V AC or 1500 V DC</b>. It covers homes, commercial, public and industrial buildings, and special locations such as construction sites, marinas, solar PV, EV charging and outdoor lighting.</p><p>It does <b>not</b> cover the supplier\'s network up to the meter, the internal design of equipment (that is the product standard), lift machinery itself, lightning protection systems of buildings (BS EN 62305), or electrical equipment of vehicles, ships and aircraft. Where equipment is outside scope, its <b>connection</b> to the installation is still inside scope.</p>',
    lk: 'Sri Lanka has no separate national wiring code in common use on our projects – contracts and consultants normally specify BS 7671, and the CEB / LECO service rules apply at the supply point. Where a local rule is stricter, it applies. <span class="chk">Confirm the current position with the reviewer.</span>',
    explore: { w: 'sort', o: { ask: 'Sort each item: is it inside the scope of BS 7671?', bins: ['Inside the scope', 'Outside the scope'], colors: ['#15803d', '#b45309'], items: [['Lighting circuits in a hotel corridor', 0], ['Wiring from the DB to a stadium floodlight mast', 0], ['CEB transformer and service cable up to the meter', 1, 'The supplier\'s network – their rules apply'], ['Internal wiring of an LED driver', 1, 'Product standard (BS EN 61347), not BS 7671'], ['Supply to a marina berth', 0, 'Section 709'], ['Roof air terminals and down conductors', 1, 'Lightning protection – BS EN 62305 (the bonding to it is in scope)'], ['Solar PV array and its DC cabling', 0, 'Section 712'], ['Lift car and its machinery', 1, 'Lift standards (BS EN 81) – the supply to the lift is in scope'], ['EV charger circuit in a car park', 0, 'Section 722'], ['Wiring inside a bus', 1, 'Vehicle equipment is excluded'], ['Temporary supply on a construction site', 0, 'Section 704'], ['Supply to the hotel\'s outdoor fountain', 0, 'Section 702']] }, prompts: ['Which items did you get wrong? Most mistakes are about "the equipment" versus "the circuit that feeds it".', 'Find Chapter 11 in your copy and read the list of exclusions.'] },
    worked: { title: 'Scoping a hotel package', intro: 'Decide which standard covers each part of a hotel electrical package.', steps: [['Main LV switchboard to all floors', 'Fixed installation from the origin, below 1000 V', 'BS 7671'], ['Lift supply', 'The circuit up to the lift isolator is the installation; the lift machine is equipment', 'BS 7671 up to the isolator, BS EN 81 beyond'], ['Lightning protection', 'Air terminals and down conductors are a separate standard; the bonding of the LPS to the MET is installation work', 'BS EN 62305 + BS 7671 bonding'], ['11 kV ring main unit', 'Above 1000 V', 'Outside BS 7671 – HV standards'], ['Pool lighting', 'A special location in Part 7', 'BS 7671 Section 702']], note: 'Write the scope split into the method statement and the O&M manual so testing and certification match.' },
    tryit: pickTry([['A 33 kV / 400 V substation feeding a factory – the 33 kV switchgear is…', ['Outside BS 7671 (above 1000 V)', 'Inside BS 7671', 'Inside only if indoors'], 0, 'BS 7671 stops at 1000 V AC.'], ['The DC string cabling of a 600 V PV array is…', ['Inside – Section 712', 'Outside – it is DC', 'Outside – the inverter maker covers it'], 0, 'DC up to 1500 V is in scope.'], ['The internal wiring of a floodlight is…', ['Outside – covered by its product standard', 'Inside – Part 5', 'Inside – Section 714'], 0, 'Equipment construction is the product standard.'], ['The cable from the DB to a lift controller is…', ['Inside BS 7671', 'Outside – lifts are excluded', 'Only the lift maker can install it'], 0, 'The supply circuit is part of the installation.'], ['Wiring of a leisure caravan pitch supply is…', ['Inside – Section 708', 'Outside – vehicles are excluded', 'Covered only by the caravan maker'], 0, 'The pitch supply is a special location.']]),
    site: ['Check the drawings: where does our scope start (origin) and end?', 'Note any HV or vendor-supplied packages that need their own test certificates.', 'Ask which edition and amendment of BS 7671 the contract names.'],
    watch: 'A contract that names an old edition still needs the current safety level – raise it with the SEE if the specification is out of date.',
    quiz: [Q('BS 7671 applies to installations up to…', ['1000 V AC / 1500 V DC', '400 V AC only', '11 kV', '50 V'], 0), Q('Which is outside the scope of BS 7671?', ['The supplier\'s network before the meter', 'A socket circuit', 'A PV installation', 'A marina'], 0, 'The distribution network has its own rules.'), Q('The connection from an installation to a lightning protection system is…', ['Covered by BS 7671 (bonding)', 'Never connected', 'Covered only by BS EN 62305', 'Not allowed'], 0), Q('The internal construction of an LED driver is covered by…', ['Its product standard', 'BS 7671 Part 5', 'BS 7671 Part 7', 'Nobody'], 0), Q('Where a local rule in Sri Lanka is stricter than BS 7671…', ['The stricter rule applies', 'BS 7671 wins', 'Ignore both', 'Ask the client to choose'], 0)],
  });

  lesson('m1', '1.2', '🛡️', 'Fundamental principles of safety', {
    regs: ['Chapter 13', 'Reg 131.1', 'Reg 132', 'Reg 134'],
    hook: 'After a fire in a shop, the inspector asks one question: "Which hazard did the designer consider, and what did they do about it?" Chapter 13 is that checklist.',
    rule: '<p>Chapter 13 states the <b>principles</b> the rest of the book delivers. An installation must give protection against:</p><ul><li><b>Electric shock</b> – direct contact with live parts and contact with metal that has become live through a fault.</li><li><b>Thermal effects</b> – fire, burns and overheating.</li><li><b>Overcurrent</b> – overload and fault currents.</li><li><b>Fault current</b> – conductors must carry it safely until it is cleared.</li><li><b>Voltage disturbances</b> – overvoltage (lightning, switching), undervoltage and electromagnetic influences.</li><li><b>Interruption of supply</b> – where loss of power is itself a danger (safety services).</li></ul><p>It also says the installation must be <b>designed</b> (132), built with suitable <b>equipment</b> (133), <b>erected</b> by competent people with good workmanship and then <b>inspected and tested</b> before use (134).</p>',
    explore: { w: 'flip', o: { cards: [['Electric shock', 'Basic protection (insulation, enclosures) + fault protection (earthing, bonding, automatic disconnection) + additional protection (30 mA RCD).'], ['Thermal effects', 'Correct cable sizing, terminations torqued, enclosures of suitable fire rating, AFDDs where required, distance from flammable materials.'], ['Overcurrent', 'MCBs, RCBOs and fuses chosen so Ib ≤ In ≤ Iz; breaking capacity at least the fault current.'], ['Fault current', 'Protective conductors big enough to carry the fault current until disconnection – adiabatic check.'], ['Overvoltage', 'SPDs where the risk assessment or the use needs them; insulation co-ordination.'], ['Loss of supply', 'Safety services (escape lighting, fire alarm) with their own sources and fire-resistant circuits.'], ['Design', 'Maximum demand, supply characteristics, conductors, protection, isolation, records.'], ['Verification', 'Inspection and testing before the installation is put into service (Part 6).']] }, prompts: ['Turn every card. For each, think of one DIMO job where it mattered.'] },
    worked: { title: 'A commercial kitchen circuit', intro: 'Go through the principles for a 32 A, 7 kW combination oven in a hotel kitchen.', steps: [['Shock', 'Metal oven, wet floor – earthed, on a 30 mA RCBO, bonding checked', 'Basic + fault + additional'], ['Thermal', 'Cable sized for 32 A in a hot kitchen (Ca for 40 °C)', 'Bigger cable'], ['Overcurrent', 'Ib 30.4 A ≤ In 32 A ≤ Iz', 'RCBO 32 A'], ['Fault current', 'CPC checked by Zs and adiabatic', 'Zs within limit'], ['Isolation', 'Local isolator for cleaning and maintenance', 'Lockable switch'], ['Verification', 'Test and record before handover', 'EIC + schedule']] },
    tryit: pickTry([['Escape lighting stopping when the supply fails is a failure of protection against…', ['Interruption of supply', 'Overcurrent', 'Electric shock'], 0, 'Safety services must keep working – Chapter 56.'], ['A loose terminal charring a terminal block is a failure of protection against…', ['Thermal effects', 'Overvoltage', 'Electric shock'], 0, 'Heat from a high-resistance joint.'], ['A lightning strike damaging the BMS is a failure of protection against…', ['Voltage disturbances (overvoltage)', 'Overload', 'Fault current'], 0, 'Section 443 / 534 – SPDs.'], ['A person getting a shock from a metal light fitting with a broken earth is a failure of…', ['Fault protection', 'Basic protection', 'Overload protection'], 0, 'The CPC failed, so automatic disconnection could not happen.'], ['A cable melting because too many circuits are bunched together is a failure to consider…', ['Overcurrent / thermal effects (grouping)', 'Shock', 'Supply interruption'], 0, 'Grouping reduces what each cable can carry.']]),
    site: ['Ask: what could go wrong with this circuit – shock, heat, overload, fault, surge, loss of power?', 'Make sure nothing is energised before it is inspected and tested.'],
    quiz: [Q('Chapter 13 of BS 7671 sets out…', ['The fundamental principles of safety', 'Cable tables', 'Test certificates', 'Special locations'], 0), Q('Which is NOT one of the hazards Chapter 13 lists?', ['Poor lighting levels', 'Electric shock', 'Thermal effects', 'Overcurrent'], 0, 'Lux levels are a lighting design matter, not BS 7671.'), Q('Safety services exist mainly to protect against…', ['Danger from interruption of supply', 'High electricity bills', 'Harmonics', 'Theft'], 0), Q('Before an installation is put into service it must be…', ['Inspected and tested', 'Painted', 'Approved by the architect', 'Used for a week'], 0), Q('Protection against overvoltage is mainly given by…', ['Surge protective devices', 'Bigger cables', 'Type C MCBs', 'Labels'], 0)],
  });

  lesson('m1', '1.3', '📖', 'Key definitions you must know', {
    regs: ['Part 2 – Definitions'],
    hook: 'Two engineers argue: "The metal sink must be bonded – it is an exposed-conductive-part." "No, it is not even an extraneous-conductive-part." Most site arguments are really arguments about definitions.',
    rule: '<p>Part 2 defines the words the rest of BS 7671 uses. Learn these precisely – a requirement often depends on one word:</p><table class="spec"><tr><td>Exposed-conductive-part</td><td>Metal of electrical equipment you can touch, not normally live, that can become live in a fault (a metal luminaire body, a DB case).</td></tr><tr><td>Extraneous-conductive-part</td><td>Metal that is not part of the electrical installation but can bring in a potential, usually earth (incoming metal water or gas pipe, structural steel).</td></tr><tr><td>Protective conductor (CPC)</td><td>Conductor for safety – connects exposed-conductive-parts to the main earthing terminal.</td></tr><tr><td>PEN conductor</td><td>One conductor doing both jobs – protective and neutral (TN-C-S supply).</td></tr><tr><td>Basic / fault protection</td><td>Protection with no fault (insulation, enclosures) / when a single fault happens (earthing, bonding, ADS).</td></tr><tr><td>Final / distribution circuit</td><td>Feeds current-using equipment or sockets / feeds a distribution board.</td></tr><tr><td>Ze, Zs</td><td>External earth fault loop impedance at the origin / the whole loop at a point of the circuit.</td></tr><tr><td>Skilled / instructed person</td><td>Has the training and experience to avoid electrical danger / is adequately advised or supervised by a skilled person.</td></tr></table>',
    explore: { w: 'flip', o: { cards: [['Exposed-conductive-part', 'Metal case of Class I equipment – earthed through the CPC.'], ['Extraneous-conductive-part', 'Metal pipe or steel that can introduce earth potential – bonded to the MET.'], ['Class I equipment', 'Basic insulation + a protective earth connection.'], ['Class II equipment', 'Double or reinforced insulation – no earth terminal (⧈ symbol).'], ['RCD / RCBO', 'Residual current device / RCD with built-in overcurrent protection.'], ['AFDD', 'Arc fault detection device – trips on dangerous arcing.'], ['SPD', 'Surge protective device – limits transient overvoltages.'], ['Origin of the installation', 'Where electrical energy is delivered – the supplier\'s terminals.'], ['Main earthing terminal (MET)', 'The terminal that connects protective conductors and bonding to the earthing conductor.'], ['Ib · In · Iz', 'Design current · rated current of the device · current-carrying capacity of the cable after factors.']] } },
    worked: { title: 'Classifying metalwork in a hotel bathroom', steps: [['Metal towel rail on the circuit', 'Part of electrical equipment, can become live in a fault', 'Exposed-conductive-part – earth it'], ['Copper hot-water pipes fed in plastic', 'Cannot bring earth potential in', 'Not extraneous – no bonding'], ['Steel bath on metal pipes from outside', 'Can introduce earth potential', 'Extraneous – bonded (unless 701.415.2 conditions allow omission)'], ['Plastic-cased extract fan, Class II', 'No earth terminal', 'Not exposed – do not earth']] },
    tryit: pickTry([['A metal-cased LED floodlight (Class I) is…', ['An exposed-conductive-part', 'An extraneous-conductive-part', 'Neither'], 0, 'It belongs to the electrical equipment.'], ['An incoming metal gas pipe is…', ['An extraneous-conductive-part', 'An exposed-conductive-part', 'A protective conductor'], 0, 'It can introduce earth potential.'], ['A conductor that combines neutral and earth is a…', ['PEN conductor', 'CPC', 'Bonding conductor'], 0, 'Found in TN-C-S supplies up to the point of separation.'], ['A circuit feeding a sub-distribution board is a…', ['Distribution circuit', 'Final circuit', 'Ring circuit'], 0, 'It does not feed equipment directly.'], ['Someone trained and experienced enough to avoid electrical danger is a…', ['Skilled person', 'Instructed person', 'Ordinary person'], 0, 'Instructed = advised or supervised by a skilled person.']]),
    site: ['Use the defined words in reports and RAMS – "earthed" and "bonded" are not the same.'],
    quiz: [Q('A metal water pipe entering a building from outside is…', ['An extraneous-conductive-part', 'An exposed-conductive-part', 'A PEN conductor', 'Class II'], 0), Q('Class II equipment has…', ['Double or reinforced insulation and no earth terminal', 'An earth terminal', 'Only SELV supply', 'A metal case that must be bonded'], 0), Q('Ze is the earth fault loop impedance…', ['External to the installation, at the origin', 'At the furthest socket', 'Of the CPC only', 'Of the RCD'], 0), Q('A final circuit is one that…', ['Supplies current-using equipment or sockets', 'Feeds a distribution board', 'Is the last circuit installed', 'Has no CPC'], 0), Q('Iz is…', ['The current-carrying capacity of the cable in its installed conditions', 'The device rating', 'The design current', 'The fault current'], 0)],
  });

  lesson('m1', '1.4', '📝', 'Assessing the general characteristics', {
    regs: ['Part 3 · Chapters 31–36', 'Reg 311.1', 'Reg 313.1'],
    hook: 'A designer sized every MCB at 6 kA – then the site test at the main board measured 9.8 kA. Nobody had asked the supply characteristics before the design started.',
    rule: '<p>Before designing, find out the installation\'s <b>general characteristics</b> (Part 3):</p><ul><li><b>Purposes, supplies and structure</b> (Ch 31): maximum demand and diversity, number and type of live conductors, the earthing arrangement, and the supply: nominal voltage, frequency, <b>prospective fault current at the origin</b>, <b>Ze</b>, and the rating of the supply protective device.</li><li><b>External influences</b> (Ch 32 / Appendix 5): water, dust, temperature, impact, corrosion, sun…</li><li><b>Compatibility</b> (Ch 33): equipment that could harm other equipment or the supply (harmonics, starting currents).</li><li><b>Maintainability</b> (Ch 34): how and how often it will be maintained.</li><li><b>Safety services</b> (Ch 35) and <b>continuity of service</b> (Ch 36).</li></ul><p>These values are obtained from the supplier, by calculation, or by measurement – and are recorded on the certificate.</p>',
    lk: 'Ask CEB / LECO for the declared earthing arrangement, Ze and fault level – and measure them. Many urban supplies are close to a transformer, so fault levels above 6 kA are common at large sites.',
    explore: { w: 'profile', o: {}, prompts: ['Set TT with Ze 0.35 Ω – what warning do you get, and why?', 'Raise the fault current to 12 kA – what changes for the devices?', 'Make the maximum demand larger than the supply fuse.'] },
    worked: { title: 'An office fit-out', intro: 'Supplier says: TN-C-S, 230 / 400 V, 100 A per phase. You measure Ze = 0.21 Ω.', steps: [['Prospective fault current', 'Ipf = U0 / Ze = 230 / 0.21', '1095 A ≈ 1.1 kA (single-phase)'], ['Three-phase fault level', 'About twice the single-phase value', '≈ 2.2 kA'], ['Device breaking capacity', '6 kA devices are enough', 'OK'], ['Earthing', 'PME – check bonding sizes (Table 54.8)', '10 mm² for a 35 mm² neutral'], ['Record', 'Ze, Ipf, earthing, supply device on the EIC', 'Done']] },
    tryit: () => { const ze = rnd(0.05, 0.8, 0.01); return { q: `The measured Ze at the origin is <b>${ze} Ω</b>. What is the prospective fault current (single-phase, U0 230 V) in <b>kA</b>?`, a: 230 / ze / 1000, unit: 'kA', hint: 'Ipf = U0 / Ze, then divide by 1000.', how: `Ipf = 230 / ${ze} = ${R(230 / ze, 0)} A = ${R(230 / ze / 1000, 2)} kA.` }; },
    site: ['Measure Ze with the main earthing conductor disconnected and the installation isolated – reconnect it immediately after.', 'Measure prospective fault current at the origin and record the highest value.', 'Write the supply device type and rating on the certificate.'],
    watch: 'Never leave the main earthing conductor disconnected – lock off the installation while you measure Ze.',
    quiz: [Q('Which value is part of the supply characteristics you must find out?', ['Ze', 'Lux level', 'Paint colour', 'Cable brand'], 0), Q('Ipf at the origin is calculated from…', ['U0 / Ze', 'Ze × U0', 'Ib / Iz', 'U0 × 1.45'], 0), Q('Chapter 34 deals with…', ['Maintainability', 'Batteries', 'Bathrooms', 'Colours'], 0), Q('A 0.1 Ω Ze gives a single-phase prospective fault current of about…', ['2.3 kA', '230 A', '23 kA', '0.23 kA'], 0, '230 / 0.1 = 2300 A.'), Q('External influences are classified in…', ['Chapter 32 / Appendix 5', 'Chapter 64', 'Section 701', 'Part 8'], 0)],
  });

  // ================================================================ M2 · Earthing systems and supply
  lesson('m2', '2.1', '〰️', 'Live conductors and supply types', {
    regs: ['Chapter 31', 'Reg 312.1'],
    hook: 'A new site supervisor reads 400 V between two "230 V" terminals and thinks the meter is broken. It is not – it is three-phase.',
    rule: '<p>Our supplies are <b>230 V</b> line to neutral (U0) and <b>400 V</b> line to line, <b>50 Hz</b>. 230 V is the r.m.s. value – the peak is 230 × √2 ≈ <b>325 V</b>. Three phases are 120° apart, so the voltage between two lines is 230 × √3 ≈ <b>400 V</b>.</p><p>BS 7671 describes supplies by the number of <b>live conductors</b> (single-phase two-wire, three-phase four-wire…) and by the <b>earthing arrangement</b> (next lesson). Current: single-phase I = P / (U0 × pf); three-phase I = P / (√3 × U × pf) with U = 400 V.</p>',
    explore: { w: 'wave', o: { mode: '3' }, prompts: ['Switch to "Line voltage L1–L2": why is it larger than either phase?', 'Watch the three phasors – at every instant the three values add up to zero. That is why a balanced three-phase load needs no neutral current.'] },
    worked: { title: 'Current of a three-phase chiller', intro: '30 kW, power factor 0.9, 400 V three-phase.', steps: [['Formula', 'I = P / (√3 × U × pf)', ''], ['Numbers', '30 000 / (1.732 × 400 × 0.9)', ''], ['Result', '30 000 / 623.5', '48.1 A per phase'], ['Single-phase compare', 'The same 30 kW on one phase: 30 000 / (230 × 0.9)', '145 A – why big loads are three-phase']] },
    tryit: () => { const three = Math.random() < 0.5, kw = rnd(2, 40, 0.5), pf = rnd(0.8, 1, 0.01); const a = three ? (kw * 1000) / (Math.sqrt(3) * 400 * pf) : (kw * 1000) / (230 * pf); return { q: `A ${three ? 'three-phase 400 V' : 'single-phase 230 V'} load of <b>${kw} kW</b> at power factor <b>${pf}</b>. What current does it draw${three ? ' per phase' : ''}?`, a, unit: 'A', hint: three ? 'I = P / (√3 × 400 × pf)' : 'I = P / (230 × pf)', how: three ? `${kw * 1000} / (1.732 × 400 × ${pf}) = ${R(a, 1)} A` : `${kw * 1000} / (230 × ${pf}) = ${R(a, 1)} A` }; },
    site: ['Check phase rotation before connecting three-phase motors.', 'Balance single-phase loads across L1, L2 and L3 on the DB schedule.'],
    quiz: [Q('The voltage between two lines of a 230 / 400 V supply is…', ['400 V', '230 V', '460 V', '325 V'], 0), Q('The peak of a 230 V r.m.s. supply is about…', ['325 V', '230 V', '400 V', '163 V'], 0), Q('Three-phase current is calculated with…', ['P / (√3 × U × pf)', 'P / (U × pf)', 'P × √3', 'U / P'], 0), Q('The phases of a three-phase supply are…', ['120° apart', '90° apart', '180° apart', 'in phase'], 0), Q('In Sri Lanka the supply frequency is…', ['50 Hz', '60 Hz', '100 Hz', '400 Hz'], 0)],
  });

  lesson('m2', '2.2', '⏚', 'TN-S, TN-C-S (PME) and TT', {
    regs: ['Reg 312.2', 'Figures 3.8–3.10 (Part 3)', 'Reg 411.4 (TN)', 'Reg 411.5 (TT)'],
    hook: 'Two identical showrooms, one in Colombo and one in a rural town. Same circuits, same MCBs – but in one the MCB clears an earth fault in 10 ms and in the other it never trips. The difference is the earthing system.',
    rule: '<p>The letters tell you how the source and the installation are earthed:</p><ul><li>First letter: <b>T</b> – the source has a direct connection to earth; <b>I</b> – isolated or earthed through a high impedance.</li><li>Second letter: <b>T</b> – exposed metal is earthed by the installation\'s own electrode; <b>N</b> – it is connected to the source earth through the supply\'s conductors.</li><li>After the dash: <b>S</b> – separate neutral and protective conductors; <b>C</b> – combined (PEN).</li></ul><table class="spec"><tr><td>TN-S</td><td>Separate earth from the supplier (cable sheath). Typical Ze up to about 0.8 Ω.</td></tr><tr><td>TN-C-S (PME)</td><td>Combined PEN in the supply, separated at the cut-out. Typical Ze up to about 0.35 Ω.</td></tr><tr><td>TT</td><td>No earth from the supplier – your own electrode. The fault returns through the ground, so the current is small and <b>RCDs give fault protection</b>.</td></tr></table><p>In TN systems a low Zs lets the MCB or fuse disconnect quickly. In TT the condition is <b>RA × IΔn ≤ 50 V</b>.</p>',
    lk: 'Many CEB / LECO consumer supplies are TT with an electrode at each building, so RCDs are essential. Larger sites with their own transformer can choose TN-S. <span class="chk">Confirm with the supplier for each project.</span>',
    explore: { w: 'earth', o: { sys: 'TN-C-S' }, prompts: ['Switch between TN-S, TN-C-S and TT and watch the fault path change.', 'In TT, turn the RCD off – what happens to the touch voltage?', 'In TN-C-S, increase R1+R2 until the MCB is too slow.'] },
    worked: { title: 'Why an MCB cannot protect a TT circuit', intro: 'TT, installation electrode RA = 100 Ω, supply electrode about 10 Ω, circuit R1+R2 0.6 Ω, Type B 32 A MCB.', steps: [['Loop impedance', '100 + 10 + 0.6 + 0.35 (supply)', '≈ 111 Ω'], ['Fault current', '230 / 111', '≈ 2.1 A'], ['Instant trip needs', '5 × 32 A', '160 A – the MCB will not trip'], ['Touch voltage', '2.1 A × 100 Ω', '≈ 207 V on the case'], ['Solution', '30 mA RCD: RA × IΔn = 100 × 0.03 = 3 V ≤ 50 V', 'RCD gives fault protection']] },
    tryit: () => { const RA = rnd(20, 300, 10), RB = rnd(2, 20, 1); const a = 230 / (RA + RB + 1); return { q: `TT system: installation electrode RA = <b>${RA} Ω</b>, supply electrode RB = <b>${RB} Ω</b>, rest of the loop about 1 Ω. What earth fault current flows (A)?`, a, unit: 'A', tol: 0.04, hint: 'I = 230 / (RA + RB + 1)', how: `230 / (${RA} + ${RB} + 1) = ${R(a, 2)} A – far too small for an MCB.` }; },
    site: ['Identify the earthing system at the cut-out before you design or test – it decides the protection.', 'For TT, measure RA and check RA × IΔn ≤ 50 V.'],
    write: 'Which earthing system does your current project have? How did you confirm it, and what did it mean for the choice of RCDs?',
    quiz: [Q('In TN-C-S the protective and neutral functions in the supply are…', ['Combined in a PEN conductor', 'Separate all the way', 'Not provided', 'Provided by an electrode only'], 0), Q('In a TT system fault protection is usually given by…', ['RCDs', 'MCBs alone', 'Fuses alone', 'Bonding only'], 0, 'The ground path makes the fault current too small for overcurrent devices.'), Q('The TT condition for an RCD is…', ['RA × IΔn ≤ 50 V', 'Zs ≤ 0.8 Ω', 'RA ≤ 1 Ω', 'IΔn ≥ 300 mA'], 0), Q('The second letter "N" means exposed metal is connected…', ['To the source earth through the supply conductors', 'To a local electrode only', 'To nothing', 'To the neutral at every socket'], 0), Q('A typical maximum Ze for a TN-C-S supply is about…', ['0.35 Ω', '0.8 Ω', '21 Ω', '200 Ω'], 0)],
  });

  lesson('m2', '2.3', '🏥', 'IT systems and where they are used', {
    regs: ['Reg 312.2.3', 'Reg 411.6'],
    hook: 'In an operating theatre, a fault on the surgeon\'s equipment must <b>not</b> switch off the supply in the middle of an operation. The IT system was invented for that.',
    rule: '<p>In an <b>IT</b> system the source is isolated from earth (or earthed through a high impedance), while the installation\'s exposed metal is earthed. On the <b>first fault</b> to earth only a tiny capacitive current flows, so the touch voltage stays low and the supply can continue. Condition: <b>RA × Id ≤ 50 V</b> (Id = the first-fault current).</p><p>An <b>insulation monitoring device (IMD)</b> must give an alarm on the first fault so it can be found and repaired. A <b>second fault</b> on another conductor is a short circuit through the earthing – it must be disconnected like a TN or TT system.</p><p>Used for medical Group 2 locations (IT medical system), some process plant and critical control circuits.</p>',
    explore: { w: 'earth', o: { sys: 'IT', mode: 'fault' }, prompts: ['First fault: why is the touch voltage so small?', 'Switch to "IT: second fault" – now the overcurrent device has to act.'] },
    worked: { title: 'First fault in an IT system', intro: 'RA = 20 Ω, first-fault current Id = 0.5 A (leakage capacitance of the system).', steps: [['Touch voltage', 'RA × Id = 20 × 0.5', '10 V'], ['Condition', '10 V ≤ 50 V', 'Complies – supply may continue'], ['Alarm', 'IMD signals the fault', 'Find and fix before a second fault']] },
    tryit: () => { const RA = rnd(5, 120, 5), Id = rnd(0.1, 1.5, 0.1); return { q: `IT system: RA = <b>${RA} Ω</b>, first-fault current Id = <b>${Id} A</b>. What is the touch voltage (V)?`, a: RA * Id, unit: 'V', hint: 'RA × Id', how: `${RA} × ${Id} = ${R(RA * Id, 1)} V – ${RA * Id <= 50 ? 'within' : 'above'} the 50 V limit.` }; },
    site: ['Test the IMD alarm during commissioning and record it.', 'Label IT system boards clearly – they behave differently from TN boards.'],
    quiz: [Q('On the first earth fault in an IT system…', ['An alarm is given and supply can continue', 'The supply must disconnect in 0.4 s', 'Nothing can be detected', 'The RCD trips'], 0), Q('The IT condition for the first fault is…', ['RA × Id ≤ 50 V', 'Zs ≤ 0.35 Ω', 'Id ≥ 30 mA', 'RA ≤ 1 Ω'], 0), Q('An IMD is…', ['An insulation monitoring device', 'An isolating main disconnector', 'An induction motor drive', 'An indoor meter'], 0), Q('IT systems are typical in…', ['Operating theatres (Group 2)', 'Domestic kitchens', 'Car parks', 'Shop windows'], 0), Q('A second fault on another phase must be…', ['Disconnected automatically', 'Ignored until the next inspection', 'Left on because of the IMD', 'Bonded'], 0)],
  });

  lesson('m2', '2.4', '⚡', 'Ze, prospective fault current and breaking capacity', {
    regs: ['Reg 313.1', 'Reg 434.1', 'Reg 434.5.1', 'Reg 536.1'],
    hook: 'A 6 kA MCB was fitted 15 m from a 1 MVA transformer. On the first short circuit it did not break the current – it exploded. The fault level was 18 kA.',
    rule: '<p><b>Ze</b> is the impedance of the supply part of the earth fault loop. The lower it is, the higher the <b>prospective fault current</b>: Ipf ≈ U0 / Ze. Measure both the prospective short-circuit current (line–neutral) and the prospective earth fault current (line–earth) and record the higher.</p><p>Every protective device must be able to <b>break</b> the highest fault current where it is installed – its <b>breaking capacity</b> (Icn for MCBs, e.g. 6 kA or 10 kA). A lower-rated device is allowed only when an upstream device gives <b>back-up protection</b> and the manufacturer confirms the combination. For three-phase supplies take roughly twice the single-phase value as a quick estimate.</p>',
    explore: { w: 'ze', o: {}, prompts: ['Lower Ze to 0.03 Ω – which devices are still suitable?', 'Switch to three-phase.'] },
    worked: { title: 'Choosing breaking capacity', intro: 'Measured Ze at a new main board = 0.018 Ω (close to the transformer).', steps: [['Single-phase PFC', '230 / 0.018', '12 780 A ≈ 12.8 kA'], ['Three-phase estimate', '2 × 12.8', '≈ 25.6 kA'], ['Main board devices', 'MCCBs ≥ 36 kA or BS 88 fuses', 'Not 6 kA MCBs'], ['Downstream DBs', 'Fault level falls along each cable – recalculate at each board', 'Often 6–10 kA']] },
    tryit: () => { const ze = rnd(0.02, 0.6, 0.01), three = Math.random() < 0.4, a = (230 / ze / 1000) * (three ? 2 : 1); return { q: `Ze = <b>${ze} Ω</b>. Estimate the ${three ? '<b>three-phase</b> (≈ 2 × single-phase)' : 'single-phase'} prospective fault current in kA.`, a, unit: 'kA', tol: 0.04, hint: 'U0 / Ze in A, ÷ 1000' + (three ? ', then × 2' : ''), how: `230 / ${ze} = ${R(230 / ze, 0)} A${three ? ' × 2' : ''} = ${R(a, 2)} kA` }; },
    site: ['Measure PFC at the origin and every DB; write it on the DB schedule.', 'Check the Icn printed on every MCB against the fault level.'],
    quiz: [Q('If Ze halves, the prospective fault current…', ['Roughly doubles', 'Halves', 'Stays the same', 'Becomes zero'], 0), Q('A device must be able to break…', ['The highest fault current where it is installed', 'Its rated current only', '6 kA always', 'The load current'], 0), Q('Icn on an MCB means…', ['Its rated short-circuit breaking capacity', 'Its rated current', 'Its trip curve', 'Its colour'], 0), Q('A lower breaking capacity is acceptable when…', ['An upstream device gives back-up protection confirmed by the maker', 'The cable is short', 'It is a Type B', 'It is indoors'], 0), Q('Which values do you record at the origin?', ['The higher of PSCC and PEFC', 'Only Zs', 'Only lux', 'The insulation resistance'], 0)],
  });

  lesson('m2', '2.5', '🔌', 'PME risks and the broken PEN conductor', {
    regs: ['Reg 411.4', 'Table 54.8', 'Reg 708.411.4', 'Reg 722.411.4.1'],
    hook: 'One evening every tap, radiator and car charger in a street gave tingles. A PEN joint in the street had corroded open. No MCB or RCD tripped – nothing "saw" a fault.',
    rule: '<p>In a <b>TN-C-S (PME)</b> supply the neutral and earth share one PEN conductor. If that PEN <b>breaks</b> upstream, load current returns through the installation\'s earthing and bonding and the ground – every earthed metal part can rise towards line voltage. Protective devices do not see this as a fault.</p><p>BS 7671 handles the risk by:</p><ul><li>sizing <b>main protective bonding</b> from the supply neutral (Table 54.8), so it can carry diverted current;</li><li>restricting PME earthing for <b>caravans and boats</b> (Sections 708, 709), some <b>outdoor EV charging</b> (722 – open-PEN devices or a TT electrode), and the supply to construction-site equipment (704);</li><li>the supplier connecting the PEN to earth at many points (protective multiple earthing).</li></ul>',
    explore: { w: 'earth', o: { sys: 'TN-C-S', mode: 'pen' }, prompts: ['Increase the load – what happens to the voltage on earthed metal?', 'Why can an RCD not detect this?'] },
    worked: { title: 'Voltage on earthed metal after a broken PEN', intro: 'Load 3 kW on the faulty phase, earth path resistance about 20 Ω.', steps: [['Load resistance', '230² / 3000', '17.6 Ω'], ['Current through earth path', '230 / (17.6 + 20)', '6.1 A'], ['Voltage on earthed metal', '6.1 × 20', '≈ 122 V'], ['Who is at risk', 'Anyone touching earthed metal and true earth – outdoors, a car, a caravan', 'Why PME is restricted outdoors']] },
    tryit: () => { const kw = rnd(1, 8, 0.5), Re = rnd(5, 50, 5), Rl = (230 * 230) / (kw * 1000), a = (230 * Re) / (Re + Rl); return { q: `Broken PEN: load ${kw} kW, earth path resistance ${Re} Ω. Estimate the voltage on earthed metal (V).`, a, unit: 'V', tol: 0.04, hint: 'Rload = 230² / P; U = 230 × Re / (Re + Rload)', how: `Rload = ${R(Rl, 1)} Ω; U = 230 × ${Re} / (${Re} + ${R(Rl, 1)}) = ${R(a, 0)} V` }; },
    site: ['On PME supplies, check bonding sizes against the supply neutral, not the circuit sizes.', 'Outdoor EV chargers on PME: confirm the open-PEN protection method.'],
    watch: 'Never use a PME earth for a supply to a boat or a caravan pitch.',
    quiz: [Q('A broken PEN conductor is dangerous because…', ['Earthed metal can rise towards line voltage with no device tripping', 'It trips every RCD', 'It increases Zs slightly', 'It reverses polarity'], 0), Q('PME main bonding is sized from…', ['The supply neutral conductor (Table 54.8)', 'The largest circuit', 'Half the CPC', '2.5 mm² always'], 0), Q('PME earthing must not be used for…', ['Boats in a marina', 'Office lighting', 'A DB in a house', 'Sockets in a shop'], 0), Q('For an outdoor EV charger on PME the designer can…', ['Use an open-PEN detection device or a TT electrode', 'Ignore the risk', 'Remove the CPC', 'Use a Type AC RCD only'], 0), Q('PME stands for…', ['Protective multiple earthing', 'Primary main earth', 'Phase meter earth', 'Power monitor equipment'], 0)],
  });

  // ================================================================ M3 · Identification and wiring systems
  lesson('m3', '3.1', '🎨', 'Conductor colours and identification', {
    regs: ['Section 514', 'Table 51', 'Reg 514.14'],
    hook: 'An old building has red and black cables; the new extension has brown and blue. A trainee connects "black to black" – one was a neutral, the other a line.',
    rule: '<p>Conductors must be identified by colour or marking (Table 51):</p><table class="spec"><tr><td>Line – single-phase</td><td>Brown</td></tr><tr><td>Lines – three-phase</td><td>Brown (L1), black (L2), grey (L3)</td></tr><tr><td>Neutral</td><td>Blue</td></tr><tr><td>Protective conductor</td><td>Green-and-yellow – for nothing else</td></tr><tr><td>Functional earth</td><td>Cream</td></tr></table><p>A blue conductor used as a line (switch wires in twin and earth) must be sleeved or marked brown at its ends. Where old colours (red line, black neutral) and new colours meet in one installation, a <b>warning notice</b> must be fixed at the board (514.14). Circuits must also be labelled and a <b>circuit chart</b> provided (514.9).</p>',
    explore: { w: 'sort', o: { ask: 'Which function does each conductor have in a modern installation?', bins: ['Line', 'Neutral', 'Protective'], colors: ['#a16207', '#2563eb', '#15803d'], items: [['Brown', 0], ['Black (three-phase)', 0, 'L2'], ['Grey', 0, 'L3'], ['Blue', 1], ['Green-and-yellow', 2], ['Blue sleeved brown at the switch', 0, 'A switch wire'], ['Bare copper sleeved green-and-yellow', 2, 'The CPC of twin and earth'], ['Red (in an old installation)', 0, 'Old colour for line']] } },
    worked: { title: 'Alteration to an old installation', steps: [['Find the old colours', 'Red line, black neutral', 'Pre-2004 colours'], ['Join new cable', 'Brown to red, blue to black', 'Match function, not colour'], ['Mark', 'Fit the "two colour versions" notice at the DB', 'Reg 514.14'], ['Record', 'Circuit chart updated', 'Reg 514.9']] },
    tryit: pickTry([['The L2 conductor of a three-phase circuit is…', ['Black', 'Grey', 'Blue'], 0, 'L1 brown, L2 black, L3 grey.'], ['A switch wire in twin and earth (blue) must be…', ['Sleeved / marked brown at its ends', 'Left blue', 'Sleeved green-and-yellow'], 0, 'It is a line conductor.'], ['Green-and-yellow may be used for…', ['Protective conductors only', 'Any conductor if marked', 'Neutral in emergencies'], 0, 'Never for anything else.'], ['Mixed old and new colours in one installation need…', ['A warning notice at the DB', 'Nothing', 'Rewiring'], 0, 'Reg 514.14.'], ['In an old red/black installation, black is usually…', ['Neutral', 'Line', 'Earth'], 0, 'Confirm by testing, never by colour alone.']]),
    site: ['Never trust colours alone on old installations – prove with a test.', 'Check every board has an up-to-date circuit chart.'],
    quiz: [Q('L3 of a three-phase supply is…', ['Grey', 'Black', 'Brown', 'Blue'], 0), Q('Neutral is…', ['Blue', 'Black', 'Grey', 'Brown'], 0), Q('Green-and-yellow is reserved for…', ['Protective conductors', 'Neutral', 'Switch wires', 'Data cables'], 0), Q('Old and new colours together require…', ['A warning notice', 'No action', 'New CPCs', 'An RCD'], 0), Q('A circuit chart is required by…', ['Reg 514.9', 'Reg 701.1', 'Reg 643.8', 'Reg 559.1'], 0)],
  });

  lesson('m3', '3.2', '🌧️', 'Choosing a wiring system for the environment', {
    regs: ['Chapter 51', 'Section 522', 'Appendix 5'],
    hook: 'A seaside hotel\'s façade uplights failed in eight months: white PVC trunking cracked in the sun, steel screws rusted, and water got into the IP54 fittings during monsoon rain.',
    rule: '<p>Equipment and wiring systems must suit the <b>external influences</b> where they are installed (Section 522). BS 7671 codes them (Appendix 5): <b>AA</b> ambient temperature, <b>AD</b> water, <b>AE</b> solid objects and dust, <b>AF</b> corrosion, <b>AG</b> impact, <b>AN</b> solar radiation, and more.</p><p>The <b>IP code</b> shows protection against solids (first digit) and water (second digit); <b>IK</b> shows impact resistance. Ambient temperature also reduces cable capacity (factor Ca). Where the equipment itself is not suitable, give extra protection (enclosure, shading) – the result must be equivalent.</p>',
    lk: 'Coastal salt air (Colombo, Galle, Trincomalee), monsoon rain and strong sun all at once: specify UV-resistant sheaths, stainless or galvanised fixings and at least IP65 for façade and landscape lighting.',
    explore: { w: 'extinf', o: {}, prompts: ['Set an outdoor car-park column in a coastal town: what IP and fixings do you need?', 'Change the ambient to 45 °C – watch Ca fall.'] },
    worked: { title: 'Façade lighting on a coastal hotel', steps: [['Water', 'Rain from all directions + cleaning jets', 'AD5 → IPX5'], ['Dust', 'Light dust, sand', 'AE4 → IP5X'], ['Combine', 'IP5X + IPX5', 'IP65 minimum'], ['Corrosion', 'Salt air', 'AF2 → stainless fixings, sealed glands'], ['Sun', 'Direct sun', 'AN3 → UV-stable cable, no white PVC trunking'], ['Temperature', 'Roof parapet 45 °C', 'Ca 0.79 (PVC) – size cables up']] },
    tryit: pickTry([['A wash-down area in a food factory (water jets) needs at least…', ['IPX5', 'IPX1', 'IPX0'], 0, 'AD5 water jets.'], ['An in-ground uplight that may stand in water needs…', ['IPX7', 'IPX4', 'IPX3'], 0, 'AD7 temporary immersion.'], ['Lighting in a cement plant (heavy dust) needs…', ['IP6X', 'IP2X', 'IP3X'], 0, 'AE6 heavy dust.'], ['Luminaires in a sports hall where balls hit them need…', ['IK08–IK10', 'IK00', 'IK02'], 0, 'AG3 high impact.'], ['Cable on a roof in direct sun needs…', ['A UV-resistant sheath', 'No special sheath', 'A green sheath'], 0, 'AN3 solar radiation.']]),
    site: ['Check the IP and IK printed on each luminaire against the drawing schedule.', 'Glands and conduit entries must keep the enclosure\'s IP rating.'],
    quiz: [Q('In IP65 the "6" means…', ['Dust-tight', 'Water jets', 'Impact', 'Corrosion'], 0), Q('External influences are coded in…', ['Appendix 5', 'Appendix 4', 'Part 6', 'Table 41.3'], 0), Q('AN codes describe…', ['Solar radiation', 'Water', 'Animals', 'Altitude'], 0), Q('If a luminaire is not suitable for its location you may…', ['Add protection giving an equivalent result', 'Install it anyway', 'Lower the voltage', 'Use a bigger MCB'], 0), Q('High ambient temperature makes a cable…', ['Carry less current (Ca < 1)', 'Carry more current', 'No different', 'Need no CPC'], 0)],
  });

  lesson('m3', '3.3', '🔥', 'Fire spread, penetrations and cable support', {
    regs: ['Section 527', 'Reg 527.2', 'Reg 521.10.202', 'Reg 422.2'],
    hook: 'After a riser fire in a hotel, the investigators found 40 cables through the fire-rated floor slab – and a 100 mm gap round them, never sealed. Smoke reached five floors in minutes.',
    rule: '<p><b>Sealing penetrations</b> (527.2): where a wiring system passes through a wall, floor or ceiling that has a fire rating, the opening must be sealed to the same fire resistance – and the inside of conduit, ducting and trunking too (where the internal area exceeds the limit). Temporary seals during work; permanent seals on completion.</p><p><b>Premature collapse</b> (521.10.202): wiring systems must be supported so they will not fall early in a fire and trap people – non-metallic clips, ties or trunking alone are not enough in escape routes. Use metal or fire-resistant fixings.</p><p><b>Escape routes</b> (422.2): keep wiring in escape routes to a minimum, and protect it.</p>',
    explore: { w: 'fire', o: {}, prompts: ['Turn the fire-stopping on and off.', 'Switch to "cables over an escape route" and change the support.'] },
    worked: { title: 'Cable tray through a fire wall', steps: [['Wall rating', 'From the fire strategy drawing', '60 min'], ['Product', 'Fire batt / intumescent sealant tested for the cable type and tray', '60 min rated'], ['Install', 'To the maker\'s tested detail – no gaps', 'Photo record'], ['Label', 'Fire-stopping label with date and installer', 'For future alterations'], ['After alterations', 'Re-seal any opening you make', 'Inspector checks']] },
    tryit: pickTry([['Plastic trunking with plastic lids over a hotel corridor ceiling must have…', ['Additional metal / fire-resistant supports', 'Nothing more', 'Bigger lids'], 0, '521.10.202 – premature collapse.'], ['After pulling a new cable through a sealed fire wall you must…', ['Re-seal the opening to the wall\'s rating', 'Leave it for the fire contractor without telling anyone', 'Fill it with foam from the store'], 0, 'Use a tested, rated product.'], ['Cable ties alone holding cables in an escape route are…', ['Not acceptable unless fire-resistant', 'Always acceptable', 'Required'], 0, 'Use metal ties or fixings.'], ['The fire rating needed for a penetration seal is…', ['The same as the element it passes through', 'Always 30 minutes', 'Not specified'], 0, '527.2.']]),
    site: ['Photograph every fire-stopped penetration before ceilings close.', 'Check that cable baskets and trunking in corridors have metal primary supports.'],
    write: 'Find one fire-rated penetration on your site. Describe how it is sealed and whether it would pass inspection.',
    quiz: [Q('A penetration through a 60 min fire wall must be sealed to…', ['60 minutes', '30 minutes', 'Any rating', 'No rating'], 0), Q('Premature collapse of wiring in a fire is covered by…', ['Reg 521.10.202', 'Reg 701.1', 'Reg 643.3', 'Reg 411.3'], 0), Q('In escape routes, plastic clips alone are…', ['Not enough – add metal or fire-resistant support', 'Fine', 'Required', 'Better than metal'], 0), Q('Who seals an opening you made through a fire wall?', ['You – it must be re-sealed', 'Nobody', 'The client', 'Only after handover'], 0), Q('Section 527 deals with…', ['Minimising the spread of fire', 'Voltage drop', 'Bathrooms', 'Colours'], 0)],
  });

  lesson('m3', '3.4', '🧲', 'Proximity, segregation and EMC', {
    regs: ['Section 528', 'Reg 528.1', 'Section 444'],
    hook: 'A KNX bus kept dropping telegrams. The bus cable had been pulled in the same trunking compartment as the 230 V lighting circuits – and touched the switched outputs of an LED driver.',
    rule: '<p>BS 7671 divides circuits into two voltage bands:</p><ul><li><b>Band I</b> – ELV and data: SELV / PELV, telecoms, data, signalling, KNX / DALI bus, fire alarm signalling.</li><li><b>Band II</b> – low voltage: 230 / 400 V circuits.</li></ul><p>Band I and Band II circuits must be <b>segregated</b> (528.1): separate wiring systems, separate compartments of trunking, a partition, or every cable insulated for the highest voltage present. Safety services (fire alarm, emergency lighting) are segregated from other circuits as their own standards require (BS 5839, BS 5266).</p><p><b>EMC</b> (Section 444): keep power and data apart, avoid loops, use screened cables where needed, and bond screens properly to reduce interference.</p>',
    explore: { w: 'sort', o: { ask: 'Put each cable in the right compartment of a three-compartment trunking.', bins: ['Compartment 1 – Band II power', 'Compartment 2 – Band I data / bus', 'Separate route – safety service'], colors: ['#a16207', '#2563eb', '#dc2626'], items: [['230 V lighting circuit', 0], ['Socket ring', 0], ['KNX bus cable', 1, 'SELV bus – Band I'], ['Cat 6 data', 1], ['DALI control pair', 1, 'Treat as Band I only if the DALI cable is rated and installed as such – many DALI pairs are mains-rated and may run with power; follow the design'], ['Fire alarm cable', 2, 'BS 5839 – own route, fire-resistant'], ['Emergency lighting circuit (central battery)', 2, 'BS 5266'], ['Three-phase motor supply', 0]] } },
    worked: { title: 'Containment for a hotel corridor', steps: [['Power', 'Lighting and socket circuits', 'Compartment 1'], ['Data and KNX', 'Cat 6, KNX, CCTV', 'Compartment 2 with divider'], ['Fire alarm', 'Fire-resistant cable on its own clips', 'Separate route'], ['Crossing', 'Power crossing data at 90°', 'Minimises coupling']] },
    tryit: pickTry([['KNX bus cable may share a trunking compartment with 230 V cables when…', ['All cables are insulated for the highest voltage present, or a partition separates them', 'Never, in any case', 'Always'], 0, '528.1 options.'], ['Band I includes…', ['SELV, data and telecom circuits', '400 V motor circuits', 'Socket circuits'], 0, 'Extra-low voltage.'], ['A fire alarm cable should run…', ['On its own route, to BS 5839', 'With the socket ring', 'In the data compartment'], 0, 'Safety service.'], ['To reduce interference, power should cross data cables…', ['At right angles', 'In parallel for a long distance', 'Twisted together'], 0, 'EMC good practice.']]),
    site: ['Check trunking dividers are in place at bends and junctions, not only on straight runs.', 'Keep data cables away from LED driver outputs and VSD cables.'],
    quiz: [Q('Band I covers…', ['ELV, data and signalling circuits', 'LV power circuits', 'HV circuits', 'Earthing conductors'], 0), Q('Band I and Band II in one trunking need…', ['Segregation – partition or insulation for the highest voltage', 'Nothing', 'Different colours only', 'Bigger trunking'], 0), Q('EMC is covered mainly by…', ['Section 444', 'Section 701', 'Chapter 64', 'Table 51'], 0), Q('Fire alarm cables are segregated according to…', ['BS 5839', 'BS 7909', 'BS 1363', 'BS 88'], 0), Q('Data cables crossing power cables should cross…', ['At right angles', 'Diagonally', 'In parallel', 'Under tension'], 0)],
  });

  lesson('m3', '3.5', '🔒', 'Isolation, switching and safe isolation', {
    regs: ['Chapter 46', 'Section 537', 'Reg 537.2', 'Reg 462.3'],
    hook: 'A technician switched off "the lighting MCB", started work and got a shock. The DB had been relabelled after an alteration – the circuit was fed from another board. Nobody had tested before touching.',
    rule: '<p>BS 7671 separates four purposes – the device must suit the purpose:</p><table class="spec"><tr><td>Isolation</td><td>Cuts off all live conductors so work can be done safely. The device must have adequate contact gaps, show its position, and be lockable or otherwise secured against re-closing (537.2).</td></tr><tr><td>Switching off for mechanical maintenance</td><td>Stops machinery for non-electrical work (e.g. a fan motor) – near the machine, lockable.</td></tr><tr><td>Emergency switching / stopping</td><td>Removes danger quickly – easily reached, clearly marked (often red on yellow).</td></tr><tr><td>Functional switching</td><td>Normal on / off control (light switches, contactors).</td></tr></table><p><b>Safe isolation procedure</b>: identify the circuit, isolate, secure (lock and tag), prove the tester on a known live source, test dead between all conductors, prove the tester again – then work.</p>',
    explore: { w: 'seq', o: { ask: 'Put the safe isolation steps in the right order.', steps: ['Identify the circuit and its source(s)', 'Isolate with a suitable device', 'Lock off and fit a warning label – keep the key', 'Prove the voltage indicator on a known live source or proving unit', 'Test dead between all conductors (L–N, L–E, N–E)', 'Prove the voltage indicator again', 'Start work'], hints: ['Start with the drawings and labels.', '', 'Secure it so nobody can switch it back on.', 'Is your tester working?', '', 'Did the tester fail during the test?'], after: 'This is the procedure in the HSE guidance GS38 / the DIMO permit-to-work. Only the person holding the key may remove the lock.' } },
    worked: { title: 'Isolating a DB for work', steps: [['Identify', 'Check the drawing and the supply to the DB – any second source (generator, PV)?', 'Two sources found'], ['Isolate', 'Main switch of the DB + PV AC isolator', 'Both off'], ['Secure', 'Lock-off kits, personal padlocks, danger tags', 'Locked'], ['Prove', 'Approved voltage indicator on the proving unit', 'Working'], ['Test', 'All combinations at the incoming terminals', 'Dead'], ['Re-prove', 'Voltage indicator on the proving unit again', 'Still working → safe to work']] },
    tryit: pickTry([['A lockable rotary switch next to an extract fan motor is for…', ['Switching off for mechanical maintenance', 'Functional switching only', 'Emergency stopping'], 0, 'Lets the fan be worked on safely.'], ['A light switch is…', ['Functional switching – not an isolator', 'An isolator', 'Emergency switching'], 0, 'It is not suitable for isolation.'], ['Before testing dead, you must…', ['Prove the voltage indicator works', 'Remove the fuses', 'Ask the client'], 0, 'Prove – test – prove.'], ['A device for isolation must…', ['Be securable against unintended re-closing', 'Be red', 'Be inside the DB only'], 0, '537.2.'], ['A multimeter on resistance range is a suitable tester for proving dead…', ['No – use an approved voltage indicator', 'Yes', 'Only on single-phase'], 0, 'Use GS38 test equipment.']]),
    site: ['Always prove – test – prove. No exceptions, even for "just a light".', 'Look for second sources: generators, UPS, PV, batteries, back-feeds.'],
    watch: 'Labels on DBs are often wrong after alterations – testing is the only proof.',
    quiz: [Q('A device for isolation must…', ['Be capable of being secured in the off position', 'Be a light switch', 'Have an RCD', 'Be at the meter'], 0), Q('The correct order is…', ['Prove the tester, test dead, prove the tester again', 'Test dead only', 'Prove the tester once at the end', 'Ask a colleague'], 0), Q('Emergency switching devices should be…', ['Easily reached and clearly marked', 'Hidden', 'Inside the DB', 'Remote only'], 0), Q('Switching off for mechanical maintenance is used for…', ['Non-electrical work on machinery', 'Changing lamps', 'Testing RCDs', 'Measuring Ze'], 0), Q('Who may remove a personal lock-off?', ['Only the person who fitted it (or by an authorised procedure)', 'Anyone', 'The client', 'The storekeeper'], 0)],
  });
})();
